@Configuration
public class NativeRuntimeHintsRegistrar implements RuntimeHintsRegistrar {
    @Override
    public void registerHints(RuntimeHints hints, ClassLoader classLoader) {
        // Register reflection hints for domain entities instantiated dynamically
        hints.reflection().registerType(Customer.class,
            builder -> builder.withMembers(MemberCategory.INVOCABLE_CONSTRUCTORS,
                                           MemberCategory.DECLARED_FIELDS));

        // Register resources loaded via classpath
        hints.resources().registerPattern("templates/*.html");
    }
}
